function formatSavedScanTimestamp(value: string | number | Date | undefined): string {
  const candidate = value ? new Date(value) : null;
  if (!candidate || Number.isNaN(candidate.getTime())) {
    return 'Unknown time';
  }
  return candidate.toLocaleString([], {
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
}

function incomeDonutPolarToCartesian(centerX: number, centerY: number, radius: number, angleInDegrees: number) {
  const angleInRadians = (angleInDegrees - 90) * Math.PI / 180.0;
  return {
    x: centerX + (radius * Math.cos(angleInRadians)),
    y: centerY + (radius * Math.sin(angleInRadians)),
  };
}

const BOOKKEEPING_MONTH_INDEX: Record<string, number> = {
  january: 0,
  february: 1,
  march: 2,
  april: 3,
  may: 4,
  june: 5,
  july: 6,
  august: 7,
  september: 8,
  october: 9,
  november: 10,
  december: 11,
};

function parseRealEstatePerformanceNumber(value: unknown): number {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value;
  }

  if (typeof value === 'string') {
    const normalized = value.replace(/[$,%\s,]/g, '').trim();
    if (!normalized) {
      return 0;
    }

    const parsed = Number(normalized);
    return Number.isFinite(parsed) ? parsed : 0;
  }

  return 0;
}

function parseOptionalRealEstatePerformanceNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value;
  }

  if (typeof value === 'string') {
    const normalized = value.replace(/[$,%\s,]/g, '').trim();
    if (!normalized) {
      return null;
    }

    const parsed = Number(normalized);
    return Number.isFinite(parsed) ? parsed : null;
  }

  return null;
}

function normalizeBookkeepingOperatingHistory(trend: unknown): RealEstateOperatingSnapshot[] {
  if (!Array.isArray(trend)) {
    return [];
  }

  return trend
    .map((entry) => {
      if (!entry || typeof entry !== 'object') {
        return null;
      }

      const record = entry as Record<string, unknown>;
      const year = parseRealEstatePerformanceNumber(record.year);
      const monthIndex = BOOKKEEPING_MONTH_INDEX[String(record.month || '').trim().toLowerCase()];

      if (!Number.isFinite(year) || monthIndex === undefined) {
        return null;
      }

      const revenue = parseRealEstatePerformanceNumber(record.revenue ?? record.income);
      const expenses = parseRealEstatePerformanceNumber(record.expenses);
      const netCashFlow = parseRealEstatePerformanceNumber(record.net ?? record.net_income);
      const date = new Date(Date.UTC(year, monthIndex + 1, 0)).toISOString().slice(0, 10);

      return {
        date,
        revenue,
        expenses,
        netCashFlow,
        margin: revenue > 0 ? (netCashFlow / revenue) * 100 : null,
      } satisfies RealEstateOperatingSnapshot;
    })
    .filter((entry): entry is RealEstateOperatingSnapshot => Boolean(entry))
    .sort((left, right) => new Date(left.date).getTime() - new Date(right.date).getTime());
}

function normalizeBookkeepingOperatingSummary(summary: unknown): RealEstateOperatingSummary | null {
  if (!summary || typeof summary !== 'object') {
    return null;
  }

  const record = summary as Record<string, unknown>;
  const totalIncome = parseRealEstatePerformanceNumber(record.totalIncome);
  const totalExpenses = parseRealEstatePerformanceNumber(record.totalExpenses);
  const netIncome = parseRealEstatePerformanceNumber(record.netIncome ?? record.netCashFlow);
  const margin = parseOptionalRealEstatePerformanceNumber(record.margin)
    ?? (totalIncome > 0 ? (netIncome / totalIncome) * 100 : null);

  return {
    totalIncome,
    totalExpenses,
    netIncome,
    margin,
  };
}

function hasRealEstateOperatingActivity(
  operatingHistory: RealEstateOperatingSnapshot[],
  operatingSummary: RealEstateOperatingSummary | null,
): boolean {
  const hasHistoryActivity = operatingHistory.some((entry) =>
    Math.abs(entry.revenue || 0) > 0.005
      || Math.abs(entry.expenses || 0) > 0.005
      || Math.abs(entry.netCashFlow || 0) > 0.005,
  );

  if (hasHistoryActivity) {
    return true;
  }

  return Math.abs(operatingSummary?.totalIncome || 0) > 0.005
    || Math.abs(operatingSummary?.totalExpenses || 0) > 0.005
    || Math.abs(operatingSummary?.netIncome || 0) > 0.005;
}

function describeIncomeDonutArc(x: number, y: number, radius: number, startAngle: number, endAngle: number) {
  const start = incomeDonutPolarToCartesian(x, y, radius, endAngle);
  const end = incomeDonutPolarToCartesian(x, y, radius, startAngle);
  const largeArcFlag = endAngle - startAngle <= 180 ? '0' : '1';
  return [
    'M', start.x, start.y,
    'A', radius, radius, 0, largeArcFlag, 0, end.x, end.y,
  ].join(' ');
}

