type NetWorthChartSeriesPoint = {
  label: string;
  fullLabel: string;
  value: number;
  date: string;
};

function buildNetWorthChartSeries(
  snapshots: PortfolioSnapshot[],
  timePeriod: NetWorthTimePeriod,
  viewMode: 'assets' | 'equity',
  totalAssets: number,
  totalLiabilities: number
): NetWorthChartSeriesPoint[] {
  const isHourly = timePeriod === '1d';
  const isDaily = timePeriod === '1w' || timePeriod === '1m';

  type TimeBucket = { key: string; label: string; fullLabel: string };
  const buckets: TimeBucket[] = [];
  const now = new Date();
  let startDate: Date;

  switch (timePeriod) {
    case '1d':
      startDate = new Date(now);
      startDate.setDate(startDate.getDate() - 1);
      startDate.setMinutes(0, 0, 0);
      break;
    case '1w':
      startDate = new Date(now);
      startDate.setDate(startDate.getDate() - 7);
      startDate.setHours(0, 0, 0, 0);
      break;
    case '1m':
      startDate = new Date(now);
      startDate.setMonth(startDate.getMonth() - 1);
      startDate.setHours(0, 0, 0, 0);
      break;
    case 'YTD':
      startDate = new Date(now.getFullYear(), 0, 1);
      break;
    case '3m':
      startDate = new Date(now.getFullYear(), now.getMonth() - 2, 1);
      break;
    case '6m':
      startDate = new Date(now.getFullYear(), now.getMonth() - 5, 1);
      break;
    case '1y':
      startDate = new Date(now.getFullYear() - 1, now.getMonth(), 1);
      break;
    case '2y':
      startDate = new Date(now.getFullYear() - 2, now.getMonth(), 1);
      break;
    case '3y':
      startDate = new Date(now.getFullYear() - 3, now.getMonth(), 1);
      break;
    default:
      startDate = new Date(now.getFullYear(), now.getMonth() - 11, 1);
  }

  if (isHourly) {
    const current = new Date(startDate);
    while (current <= now) {
      const key = current.toISOString().slice(0, 16);
      const hourLabel = current.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
      const dayLabel = current.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      buckets.push({ key, label: hourLabel, fullLabel: `${dayLabel} ${hourLabel}` });
      current.setHours(current.getHours() + 1);
    }
  } else if (isDaily) {
    const current = new Date(startDate);
    while (current <= now) {
      const key = current.toISOString().split('T')[0];
      const dayLabel = current.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      const year = current.getFullYear();
      const isFirst = buckets.length === 0;
      buckets.push({ key, label: isFirst ? `${dayLabel} ${year}` : dayLabel, fullLabel: `${dayLabel}, ${year}` });
      current.setDate(current.getDate() + 1);
    }
  } else {
    const current = new Date(startDate);
    while (current <= now) {
      const key = `${current.getFullYear()}-${String(current.getMonth() + 1).padStart(2, '0')}`;
      const monthLabel = current.toLocaleDateString('en-US', { month: 'short' });
      const year = current.getFullYear();
      const isJanuary = current.getMonth() === 0;
      const isFirstMonth = buckets.length === 0;
      buckets.push({ key, label: (isFirstMonth || isJanuary) ? `${monthLabel} ${year}` : monthLabel, fullLabel: `${monthLabel} ${year}` });
      current.setMonth(current.getMonth() + 1);
    }
  }

  const bucketValues: Record<string, { value: number; date: string }> = {};
  snapshots.forEach((snapshot) => {
    let bucketKey: string;
    if (isHourly) {
      bucketKey = snapshot.date.length > 10 ? snapshot.date.slice(0, 16) : `${snapshot.date}T12:00`;
      bucketKey = `${bucketKey.slice(0, 13)}:00`;
    } else if (isDaily) {
      bucketKey = snapshot.date.split('T')[0];
    } else {
      const date = new Date(snapshot.date);
      bucketKey = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
    }

    let snapshotValue = snapshot.totalValue;
    if (viewMode === 'equity') {
      if (snapshot.netWorth !== undefined) {
        snapshotValue = snapshot.netWorth;
      } else if (totalLiabilities > 0 && totalAssets > 0) {
        snapshotValue = snapshot.totalValue * (1 - totalLiabilities / totalAssets);
      }
    }

    if (!bucketValues[bucketKey] || snapshot.date > bucketValues[bucketKey].date) {
      bucketValues[bucketKey] = { value: snapshotValue, date: snapshot.date };
    }
  });

  if (buckets.length > 0) {
    const currentBucket = buckets[buckets.length - 1];
    const currentValue = viewMode === 'equity' ? totalAssets - totalLiabilities : totalAssets;

    if (currentValue > 0) {
      bucketValues[currentBucket.key] = { value: currentValue, date: now.toISOString() };
    }
  }

  return buckets
    .map((bucket) => ({ bucket, data: bucketValues[bucket.key] }))
    .filter((entry) => entry.data !== undefined)
    .map((entry) => ({
      label: entry.bucket.label,
      fullLabel: entry.bucket.fullLabel,
      value: entry.data!.value,
      date: entry.data!.date,
    }));
}

function getVisibleAxisIndices(length: number, maxLabels: number): number[] {
  if (length <= maxLabels) return Array.from({ length }, (_, index) => index);
  const indices = new Set<number>();
  for (let index = 0; index < maxLabels; index++) {
    indices.add(Math.round(((length - 1) * index) / (maxLabels - 1)));
  }
  return Array.from(indices).sort((left, right) => left - right);
}

function formatCompactCurrency(value: number): string {
  const absValue = Math.abs(value);
  const sign = value < 0 ? '-' : '';

  if (absValue >= 1_000_000_000_000) {
    return `${sign}$${(absValue / 1_000_000_000_000).toFixed(absValue >= 10_000_000_000_000 ? 1 : 2)}T`;
  }
  if (absValue >= 1_000_000_000) {
    return `${sign}$${(absValue / 1_000_000_000).toFixed(absValue >= 10_000_000_000 ? 0 : 1)}B`;
  }
  if (absValue >= 1_000_000) {
    return `${sign}$${(absValue / 1_000_000).toFixed(absValue >= 10_000_000 ? 0 : 1)}M`;
  }
  if (absValue >= 1_000) {
    return `${sign}$${(absValue / 1_000).toFixed(absValue >= 10_000 ? 0 : 1)}k`;
  }
  return `${sign}$${absValue.toFixed(0)}`;
}

function formatStockBarTooltipValue(
  value: number,
  options: { isPercentage: boolean; isCurrency: boolean; dataInThousands: boolean }
): string {
  if (options.isPercentage) return formatPercentage(value);
  if (options.isCurrency) {
    const actualValue = options.dataInThousands ? value * 1000 : value;
    if (Math.abs(actualValue) >= 1_000_000) return formatCompactCurrency(actualValue);
    return formatCurrency(actualValue);
  }
  return value.toFixed(2);
}

function formatStockBarAxisValue(
  value: number,
  options: { isPercentage: boolean; isCurrency: boolean; dataInThousands: boolean }
): string {
  if (options.isPercentage) return `${value.toFixed(0)}%`;
  if (options.isCurrency) {
    const actualValue = options.dataInThousands ? value * 1000 : value;
    return formatCompactCurrency(actualValue);
  }
  return value.toFixed(0);
}

const generateYearLabels = (count: number, isQuarterly: boolean = false, startYear?: number): string[] => {
  const baseYear = startYear ?? new Date().getFullYear();
  const labels: string[] = [];
  if (isQuarterly) {
    for (let i = 0; i < count; i++) {
      const q = (i % 4) + 1;
      const y = baseYear + Math.floor(i / 4);
      labels.push(`${q}Q${y}`);
    }
  } else {
    for (let i = 0; i < count; i++) labels.push(`${baseYear + i}`);
  }
  return labels;
};

function sortStockFinancialsNewestFirst(financials: StockFinancials[]): StockFinancials[] {
  return [...financials].sort((left, right) => {
    const yearDiff = Number(right.fiscalYear || 0) - Number(left.fiscalYear || 0);
    if (yearDiff !== 0) return yearDiff;

    const periodDiff = (STOCK_FINANCIAL_QUARTER_ORDER[right.fiscalPeriod] || 0) - (STOCK_FINANCIAL_QUARTER_ORDER[left.fiscalPeriod] || 0);
    if (periodDiff !== 0) return periodDiff;

    return String(right.filingDate || '').localeCompare(String(left.filingDate || ''));
  });
}

function aggregateStockFinancialWindow(window: StockFinancials[], fiscalPeriod: string, fiscalYear: string): StockFinancials {
  const anchor = window[0];
  const sumField = (selector: (financial: StockFinancials) => number) => window.reduce((sum, financial) => sum + selector(financial), 0);

  return {
    ...anchor,
    fiscalPeriod,
    fiscalYear,
    revenues: sumField((financial) => financial.revenues || 0),
    netIncome: sumField((financial) => financial.netIncome || 0),
    grossProfit: sumField((financial) => financial.grossProfit || 0),
    operatingExpenses: sumField((financial) => financial.operatingExpenses || 0),
    operatingIncome: sumField((financial) => financial.operatingIncome || 0),
    earningsPerShare: sumField((financial) => financial.earningsPerShare || 0),
    earningsPerShareDiluted: sumField((financial) => financial.earningsPerShareDiluted || 0),
    totalAssets: anchor.totalAssets || 0,
    totalLiabilities: anchor.totalLiabilities || 0,
    totalEquity: anchor.totalEquity || 0,
    currentAssets: anchor.currentAssets || 0,
    currentLiabilities: anchor.currentLiabilities || 0,
    cash: anchor.cash || 0,
    operatingCashFlow: sumField((financial) => financial.operatingCashFlow || 0),
    investingCashFlow: sumField((financial) => financial.investingCashFlow || 0),
    financingCashFlow: sumField((financial) => financial.financingCashFlow || 0),
    freeCashFlow: sumField((financial) => financial.freeCashFlow || 0),
    peRatio: anchor.peRatio || 0,
    priceToBook: anchor.priceToBook || 0,
    debtToEquity: anchor.debtToEquity || 0,
  };
}

function buildRollingTtmStockFinancials(financials: StockFinancials[]): StockFinancials[] {
  const sorted = sortStockFinancialsNewestFirst(financials);
  if (sorted.length < 4) return [];

  const result: StockFinancials[] = [];
  for (let index = 0; index <= sorted.length - 4; index += 1) {
    const window = sorted.slice(index, index + 4);
    const anchor = window[0];
    result.push(aggregateStockFinancialWindow(window, anchor.fiscalPeriod, anchor.fiscalYear));
  }

  return result;
}

function getStockFinancialLabel(financial: StockFinancials, period: StockChartTimePeriod): string {
  const fiscalYear = String(financial.fiscalYear || '');
  const yearSuffix = fiscalYear.slice(-2) || fiscalYear;

  if (period === 'annual') {
    return fiscalYear ? `FY${fiscalYear}` : yearSuffix;
  }

  const fiscalPeriod = financial.fiscalPeriod || '';
  return `${fiscalPeriod}'${yearSuffix}`;
}

function getStockHistoryRangeLabel(prices: ComprehensiveStockData['historicalPrices']): string {
  if (!prices.length) return 'Price History';
  if (prices.length === 1) return 'Price History';

  const start = new Date(prices[0].date);
  const end = new Date(prices[prices.length - 1].date);
  const rangeInYears = (end.getTime() - start.getTime()) / (365.25 * 24 * 60 * 60 * 1000);

  if (rangeInYears >= 4.5) return 'Price History (5 Years)';
  if (rangeInYears >= 2.5) return 'Price History (3 Years)';
  if (rangeInYears >= 1.5) return 'Price History (2 Years)';
  return 'Price History (1 Year)';
}

function sampleStockChartConfig(chartConfig: StockModalChartConfig, maxPoints: number): StockModalChartConfig {
  if (chartConfig.data.length <= maxPoints) return chartConfig;

  const visibleIndices = getVisibleAxisIndices(chartConfig.data.length, maxPoints);
  const sampleSeries = (series?: number[]) => {
    if (!series) return undefined;
    return visibleIndices.map((index) => series[index] ?? 0);
  };

  return {
    ...chartConfig,
    data: visibleIndices.map((index) => chartConfig.data[index] ?? 0),
    xLabels: visibleIndices.map((index) => chartConfig.xLabels[index] ?? ''),
    secondaryData: sampleSeries(chartConfig.secondaryData),
    tertiaryData: sampleSeries(chartConfig.tertiaryData),
  };
}

