/* -------------------- RENOVATIONS PAGE -------------------- */
type RenovationKnownSceneAnchorDraft = {
  id: string;
  label: string;
  targetType: string;
  width: string;
  height: string;
};

type RenovationMeasurementCaptureProtocol = {
  score?: string | null;
  pass?: boolean;
  note?: string | null;
};

type RenovationMeasurementSummary = {
  enabled: boolean;
  reason?: string;
  roomsMeasured?: number;
  objectsMeasured?: number;
  appliancesFit?: number;
  processingTime?: number;
  captureProtocol?: RenovationMeasurementCaptureProtocol | string | null;
  globalCalibration?: {
    scaleFactor?: number | null;
    candidateScaleFactor?: number | null;
    consistency?: string | null;
    confidence?: string | null;
    referenceCount?: number | null;
    source?: string | null;
    rejected?: boolean;
    rejectionReason?: string | null;
    consensus?: {
      anchorTypes?: string[];
      independentAnchorCount?: number;
      photoCount?: number;
    } | null;
  } | null;
  trustSummary?: {
    trustedRoomsForPricing?: number;
    totalRooms?: number;
    trustedObjectsForPricing?: number;
    totalObjects?: number;
    untrustedRoomReasons?: Array<{ roomType: string; reasons: string[] }>;
  } | null;
  autoInferredReferenceAnchors?: {
    proposals?: number;
    groups?: number;
    added?: number;
    source?: string | null;
  } | null;
  knownSceneAnchors?: {
    specs?: number;
    candidates?: number;
    added?: number;
    source?: string | null;
  } | null;
  rooms?: Array<{
    type: string;
    dimensions: string;
    floorArea: string;
    confidence: string;
    trustedForPricing?: boolean;
    trustReasons?: string[];
  }>;
};

const RENOVATION_KNOWN_SCENE_ANCHOR_TARGETS = [
  { value: 'existing_vanity', label: 'Bathroom vanity' },
  { value: 'bathroom_mirror', label: 'Bathroom mirror' },
  { value: 'door', label: 'Door / doorway' },
  { value: 'window', label: 'Window' },
  { value: 'kitchen_sink', label: 'Kitchen sink' },
  { value: 'existing_bathtub', label: 'Bathtub' },
];

const createRenovationKnownSceneAnchorDraft = (): RenovationKnownSceneAnchorDraft => ({
  id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
  label: '',
  targetType: 'existing_vanity',
  width: '',
  height: '',
});

const compareRenovationImageNames = (
  first: { name: string; id?: string },
  second: { name: string; id?: string },
) => first.name.localeCompare(second.name, undefined, { numeric: true, sensitivity: 'base' })
  || String(first.id || '').localeCompare(String(second.id || ''));

const readRenovationImageAsDataUrl = (file: File): Promise<string> => new Promise((resolve, reject) => {
  const reader = new FileReader();
  reader.onload = (event) => resolve(String(event.target?.result || ''));
  reader.onerror = () => reject(new Error(`Failed to read ${file.name}`));
  reader.readAsDataURL(file);
});

const formatRenovationCaptureProtocol = (
  captureProtocol: RenovationMeasurementSummary['captureProtocol'],
) => {
  if (!captureProtocol) return null;

  if (typeof captureProtocol === 'string') {
    return `Capture ${captureProtocol.replace(/_/g, ' ')}`;
  }

  if (captureProtocol.score) {
    return `Capture ${captureProtocol.score}`;
  }

  return captureProtocol.pass === false ? 'Capture needs work' : 'Capture coverage checked';
};

