  const [dividendStockSortDir, setDividendStockSortDir] = useState<'desc' | 'asc'>('desc');
    const [yieldOnCostProjectionYears, setYieldOnCostProjectionYears] = useState<0 | 3 | 5 | 10>(10);
    const [yieldOnCostUseDrip, setYieldOnCostUseDrip] = useState(false);
  
  // ==================== FINANCIAL INDEPENDENCE STATE ====================
