  // Dividend growth historical: ~6% annually for dividend aristocrats
  // Real estate appreciation: ~3-4% historically
  // Rent growth: ~3% aligned with inflation
  const [expectedStockGrowth, setExpectedStockGrowth] = useState(0.07); // 7% annual stock price appreciation
  const [expectedDividendGrowth, setExpectedDividendGrowth] = useState(0.06); // 6% annual dividend growth
  const [expectedDividendYield, setExpectedDividendYield] = useState(0.025); // 2.5% average dividend yield for new investments
  const [expectedBondYield, setExpectedBondYield] = useState(0.045); // 4.5% bond yield
  const [expectedRentGrowth, setExpectedRentGrowth] = useState(0.03); // 3% annual rent increase
  const [expectedPropertyAppreciation, setExpectedPropertyAppreciation] = useState(0.035); // 3.5% annual property appreciation
  
  // Connected expense data from checking account
