                                      const loanAmount = propertyPurchaseDetails.purchasePrice - downPayment;
                                      const monthlyRate = propertyPurchaseDetails.interestRate / 100 / 12;
                                      const numPayments = propertyPurchaseDetails.mortgageTerm * 12;
                                      const monthlyMortgage = loanAmount * (monthlyRate * Math.pow(1 + monthlyRate, numPayments)) / (Math.pow(1 + monthlyRate, numPayments) - 1);
                                      const totalMonthlyExpenses = monthlyMortgage + propertyPurchaseDetails.monthlyExpenses;
                                      const monthlyCashFlow = propertyPurchaseDetails.expectedRent - totalMonthlyExpenses;
                                      const annualCashFlow = monthlyCashFlow * 12;
